contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint sentAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (sentAmount)); require(sentAmount <= 1000000000000000000000000000000);
        require(sentAmount == 10);
        require(address(this).balance >= sentAmount);
        uint oldPot = c.pot(); if (__ESBMC_reverted()) return;
        c.play{value: sentAmount}(); if (__ESBMC_reverted()) return;
        uint newPot = c.pot(); if (__ESBMC_reverted()) return;
        assert(newPot == 0 || newPot == oldPot + 10);
    }

    receive() external payable {}
}

