pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 sentAmount) internal {
        sentAmount = bound(sentAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        sentAmount = 10;
        vm.assume(address(this).balance >= sentAmount);
        uint256 oldPot;
        try c.pot() returns (uint256 __r) { oldPot = __r; } catch { return; }
        try c.play{value: sentAmount}() {} catch { return; }
        uint256 newPot;
        try c.pot() returns (uint256 __r) { newPot = __r; } catch { return; }
        assertTrue(newPot == 0 || newPot == oldPot + 10);
    }

    function testFuzz_run(uint256 sentAmount) public {
        _run(sentAmount);
    }

    receive() external payable {}
}
